@startuml
left to right direction
actor User
actor Admin
rectangle Portal {
  usecase "Log in" as Login
  usecase "View profile" as Profile
  usecase "Manage users" as Manage
}
User --> Login
User --> Profile
Admin --> Manage
@enduml

